void populate_pin_menu(QMenu& menu,int flags){bool en=flags&1;auto t=[&](char const* zh,char const* english){return QString::fromUtf8(en?english:zh);};auto add=[&](int id,QString key,QString title){auto a=menu.addAction(capture_ui::icon(key),title);a->setData(id);return a;};add(1,"pen",flags&2?t("完成编辑","Finish editing"):t("编辑","Edit"));add(2,"copy",t("复制","Copy"));add(3,"save",t("保存 PNG","Save PNG"));menu.addSeparator();add(4,"rect",flags&4?t("隐藏边框","Hide border"):t("显示边框","Show border"));add(6,"reset",t("恢复不透明","Restore opacity"));menu.addSeparator();add(5,"cancel",t("关闭","Close"));}
int menu_fixture_choice{};QString menu_fixture_output;bool menu_fixture_rendered{true},menu_fixture_owner{true};
int pin_menu(uintptr_t owner,int flags,int x,int y){
    if(!qApp||!IsWindow(HWND(owner)))return 0;
    // A native pin is not a QWidget. Give Qt the real transient-parent chain
    // instead of letting an unrelated settings/tool window own the popup.
    std::unique_ptr<QWindow> native_parent(QWindow::fromWinId(WId(owner)));
    QMenu menu;capture_ui::apply(&menu);menu.setWindowFlag(Qt::WindowStaysOnTopHint);
    populate_pin_menu(menu,flags);menu.winId();
    if(native_parent)menu.windowHandle()->setTransientParent(native_parent.get());
    else SetWindowLongPtrW(HWND(menu.winId()),GWLP_HWNDPARENT,LONG_PTR(owner));
    QTimer lifetime;QObject::connect(&lifetime,&QTimer::timeout,&menu,[&]{if(!IsWindow(HWND(owner)))menu.close();});lifetime.start(50);
    if(menu_fixture_choice)menu.setAttribute(Qt::WA_DontShowOnScreen);
    const int choice=menu_fixture_choice;
    QTimer::singleShot(0,&menu,[&,choice]{
        if(!IsWindow(HWND(owner))){menu.close();return;}
        // QMenu's native popup creation can replace the transient HWND owner.
        // Rebind after the show operation, before the nested loop accepts input.
        SetWindowLongPtrW(HWND(menu.winId()),GWLP_HWNDPARENT,LONG_PTR(owner));
        if(!choice)return;
        menu_fixture_owner=menu_fixture_owner&&GetWindow(HWND(menu.winId()),GW_OWNER)==HWND(owner);
        if(choice==-1){DestroyWindow(HWND(owner));return;}
        if(!menu_fixture_output.isEmpty()){auto image=menu.grab().toImage();menu_fixture_rendered=menu_fixture_rendered&&!image.isNull()&&qAlpha(image.pixel(image.width()/2,image.height()/2))>0&&image.save(menu_fixture_output);}
        for(auto action:menu.actions())if(action->data().toInt()==choice){menu.setActiveAction(action);QKeyEvent enter(QEvent::KeyPress,Qt::Key_Return,Qt::NoModifier);qApp->sendEvent(&menu,&enter);return;}
        menu.close();
    });
    auto chosen=menu.exec(pin_menu_position(x,y));return IsWindow(HWND(owner))&&chosen?chosen->data().toInt():0;
}

