std::map<uintptr_t,QPointer<CaptureTools>> instances;
uintptr_t create(uintptr_t owner,UiCaptureCallback cb,UiCaptureState const* state){if(!qApp||!state)return 0;auto panel=new CaptureTools(owner,cb,*state);uintptr_t id=panel->winId();instances[id]=panel;return id;}
