Fixture* active_fixture{};
void fixture_callback(uintptr_t,int command,int value,wchar_t const*) {
    if(!active_fixture)return;auto& f=*active_fixture;f.commands.push_back(command);
    if(command==CaptureSelectTool)f.state.tool=value;
    else if(command==CaptureReset){f.state.mode=0;f.state.tool=0;}
    else if(command==CaptureWidth)f.state.width=value;
    else if(command==CaptureUnderline)f.state.underline=value;
    else if(command==CaptureNumber)f.state.number=value;
    else if(command==CaptureCrop)f.state.cropping=1;
    else if(command==CaptureCropApply||command==CaptureCropCancel)f.state.cropping=0;
    if(command!=CaptureClose)update(f.id,&f.state);
}
